1	`timescale 1ns / 1ps
2	`include "CtrlDefine.vh"
3	
4	// Reservation station for one functional unit type.
5	// Entry layout (see CtrlDefine.vh):
6	//   | BUSY | OP | Q1 | Q2 | V1 | V2 | A | PC |
7	// An 8-bit tag {FU[2:0], index+1} identifies each entry on the CDB and in
8	// the RAT; 8'b0 means "no dependency".
9	// An entry is freed only when its result is broadcast on the CDB, so a tag
10	// is never reused while an older instruction still references it.
11	module RS #(
12	    parameter FU = `FU_ALU,
13	    parameter num = 3
14	)(
15	    input clk,
16	    input rst,
17	
18	    // issue interface
19	    input selected,             // allocate an entry for the instr in IS
20	    output [7:0] free_rs,       // tag of a free entry, 0 if none
21	    input [4:0] op,
22	    input [7:0] Qj, Qk,         // RAT lookup results (0 = value already valid)
23	    input [31:0] Vj, Vk,        // operand values (register file / imm / PC)
24	    input [31:0] A,             // immediate
25	    input [31:0] pc_IS,         // PC of the instr in IS
26	
27	    // dispatch interface (to FU)
28	    output en_FU,               // one-cycle pulse
29	    output [31:0] vj, vk,
30	    output [4:0] op_out,
31	    output [31:0] A_o,
32	    output [31:0] pc_FU,        // PC of the instr currently in the FU
33	    output reg [7:0] cdb_rs_rd, // tag of the instr currently in the FU
34	
35	    // CDB broadcast
36	    input [7:0] cdb_rs_num,
37	    input [31:0] cdb_data,
38	
39	    output [31:0] pc_debug
40	);
41	
42	    reg [159:0] entry [0:num-1];
43	    reg [num-1:0] dispatched;   // entry sent to FU, waiting for CDB
44	    reg fu_busy;                // FU is executing an instruction
45	    reg [31:0] pc_reg;
46	
47	    integer i;
48	
49	    function [7:0] tag_of;
50	        input integer idx;
51	        tag_of = (FU << 5) | (idx + 1);
52	    endfunction
53	
54	    // ---- free entry allocation (lowest index first) ----
55	    reg [7:0] free_tag;
56	    integer free_idx;
57	    always @ (*) begin
58	        free_tag = 8'b0;
59	        free_idx = 0;
60	        for (i = num - 1; i >= 0; i = i - 1) begin
61	            if (~entry[i][`BUSY]) begin
62	                free_tag = tag_of(i);
63	                free_idx = i;
64	            end
65	        end
66	    end
67	    assign free_rs = free_tag;
68	
69	    // ---- ready entry selection (lowest index first) ----
70	    integer disp_idx;
71	    reg disp_found;
72	    always @ (*) begin
73	        disp_found = 1'b0;
74	        disp_idx = 0;
75	        for (i = num - 1; i >= 0; i = i - 1) begin
76	            if (entry[i][`BUSY] & ~dispatched[i]
77	                & ~|entry[i][`Q1_H:`Q1_L] & ~|entry[i][`Q2_H:`Q2_L]) begin
78	                disp_found = 1'b1;
79	                disp_idx = i;
80	            end
81	        end
82	    end
83	
84	    assign en_FU  = disp_found & ~fu_busy;
85	    assign vj     = entry[disp_idx][`V1_H:`V1_L];
86	    assign vk     = entry[disp_idx][`V2_H:`V2_L];
87	    assign op_out = entry[disp_idx][`OP_H:`OP_L];
88	    assign A_o    = entry[disp_idx][`A_H:`A_L];
89	    assign pc_FU  = entry[disp_idx][`PC_H:`PC_L]; // combinational: FU latches it at the dispatch edge
90	    assign pc_debug = pc_reg;
91	
92	    // operand values captured at issue; if the needed tag is being broadcast
93	    // on the CDB this very cycle, take the CDB value directly
94	    wire qj_hit = |Qj & (Qj == cdb_rs_num);
95	    wire qk_hit = |Qk & (Qk == cdb_rs_num);
96	    wire [7:0]  Qj_adj = qj_hit ? 8'b0 : Qj;
97	    wire [7:0]  Qk_adj = qk_hit ? 8'b0 : Qk;
98	    wire [31:0] Vj_adj = qj_hit ? cdb_data : Vj;
99	    wire [31:0] Vk_adj = qk_hit ? cdb_data : Vk;
100	
101	    always @ (posedge clk or posedge rst) begin
102	        if (rst) begin
103	            for (i = 0; i < num; i = i + 1) begin
104	                entry[i] <= 160'b0;
105	            end
106	            dispatched <= {num{1'b0}};
107	            fu_busy <= 1'b0;
108	            cdb_rs_rd <= 8'b0;
109	            pc_reg <= 32'b0;
110	        end
111	        else begin
112	            // dispatch to FU
113	            if (en_FU) begin
114	                dispatched[disp_idx] <= 1'b1;
115	                fu_busy <= 1'b1;
116	                cdb_rs_rd <= tag_of(disp_idx);
117	                pc_reg <= entry[disp_idx][`PC_H:`PC_L];
118	            end
119	            else if (fu_busy & |cdb_rs_num & (cdb_rs_num == cdb_rs_rd)) begin
120	                fu_busy <= 1'b0;
121	            end
122	
123	            for (i = 0; i < num; i = i + 1) begin
124	                if (selected & |free_rs & (i == free_idx)) begin
125	                    // allocate: {PC, A, V2, V1, pad, Q2, Q1, pad, OP, BUSY}
126	                    // (entry bits 31:24 and 7:6 are unused, see CtrlDefine.vh)
127	                    entry[i] <= {pc_IS, A, Vk_adj, Vj_adj, 8'b0, Qk_adj, Qj_adj, 2'b0, op, 1'b1};
128	                    dispatched[i] <= 1'b0;
129	                end
130	                else begin
131	                    // CDB broadcast retires the entry it corresponds to
132	                    if (entry[i][`BUSY] & |cdb_rs_num & (cdb_rs_num == tag_of(i))) begin
133	                        entry[i][`BUSY] <= 1'b0;
134	                        dispatched[i] <= 1'b0;
135	                    end
136	                    // operand snoop
137	                    if (entry[i][`BUSY] & ~dispatched[i]) begin
138	                        if (|entry[i][`Q1_H:`Q1_L] & (entry[i][`Q1_H:`Q1_L] == cdb_rs_num)) begin
139	                            entry[i][`V1_H:`V1_L] <= cdb_data;
140	                            entry[i][`Q1_H:`Q1_L] <= 8'b0;
141	                        end
142	                        if (|entry[i][`Q2_H:`Q2_L] & (entry[i][`Q2_H:`Q2_L] == cdb_rs_num)) begin
143	                            entry[i][`V2_H:`V2_L] <= cdb_data;
144	                            entry[i][`Q2_H:`Q2_L] <= 8'b0;
145	                        end
146	                    end
147	                end
148	            end
149	        end
150	    end
151	
152	endmodule

