3	module sim_top;
4	    reg clk, rst;
5	
6	    RV32core core(
7	        .debug_en(1'b0),
8	        .debug_step(1'b0),
9	        .debug_addr(7'b0),
10	        .debug_data(),
11	        .clk(clk),
12	        .rst(rst),
13	        .interrupter(1'b0)
14	    );
15	
16	    initial begin
17	        clk = 0;
18	        rst = 1;
19	        #2 rst = 0;
20	    end
21	    always #1 clk = ~clk;
22	
23	endmodule

1	`timescale 1ns / 1ps
2	
3	module RAM_B(
4	    input [31:0] addra,
5	    input clka,      // normal clock
6	    input[31:0] dina,
7	    input wea, 
8	    output[31:0] douta,
9	    input[2:0] mem_u_b_h_w,
10	    input finish
11	);
12	
13	    localparam SIZE = 512;
14	    localparam ADDR_LINE = $clog2(SIZE);
15	    localparam SIM_UART_ADDR = 32'h10000000;
16	
17	    reg[7:0] data[0:SIZE-1];
18	
19	    initial	begin
20	        $readmemh("ram.mem", data);
21	    end
22	
23	    wire uart_w = wea & (addra == SIM_UART_ADDR);
24	    wire ram_w  = wea & (addra != SIM_UART_ADDR) & ~|addra[31:ADDR_LINE];
25	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
26	
27	    // write: byte / halfword / word, little endian
28	    always @ (negedge clka) begin
29	        if (ram_w) begin
30	            data[addr] <= dina[7:0];
31	            if (mem_u_b_h_w[0] | mem_u_b_h_w[1])
32	                data[addr + 1] <= dina[15:8];
33	            if (mem_u_b_h_w[1]) begin
34	                data[addr + 2] <= dina[23:16];
35	                data[addr + 3] <= dina[31:24];
36	            end
37	        end
38	    end
39	
40	    // read: word / halfword / byte with sign or zero extension
41	    assign douta = (addra == SIM_UART_ADDR) ? 32'b0 :
42	        |addra[31:ADDR_LINE] ? 32'b0 :
43	        mem_u_b_h_w[1] ? {data[addr + 3], data[addr + 2],
44	                    data[addr + 1], data[addr]} :
45	        mem_u_b_h_w[0] ? {mem_u_b_h_w[2] ? 16'b0 : {16{data[addr + 1][7]}},
46	                    data[addr + 1], data[addr]} :
47	        {mem_u_b_h_w[2] ? 24'b0 : {24{data[addr][7]}}, data[addr]};
48	
49	    // UART simulation: latch the character written to SIM_UART_ADDR,
50	    // print it when the store retires (finish).
51	    reg uart_addr_valid;
52	    reg[7:0] uart_char;
53	
54	    initial begin
55	        uart_addr_valid = 0;
56	        uart_char = 0;
57	    end
58	
59	    always @ (negedge clka) begin
60	        if (uart_w) begin
61	            uart_addr_valid <= 1'b1;
62	            uart_char <= dina[7:0];
63	        end
64	        else if (finish & uart_addr_valid) begin
65	            $write("%c", uart_char);
66	            uart_addr_valid <= 1'b0;
67	        end
68	    end
69	
70	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_jump(
4		input clk, EN, JALR,
5		input[3:0] cmp_ctrl,
6		input[31:0] rs1_data, rs2_data, imm, PC,
7		output[31:0] PC_jump, PC_wb,
8		output is_jump, finish
9	);
10	
11		wire cmp_res;
12	    reg state;
13	    assign finish = state == 1'b1;
14		initial begin
15	        state = 0;
16	    end
17	
18		reg JALR_reg;
19		reg[3:0] cmp_ctrl_reg = 0;
20		reg[31:0] rs1_data_reg = 0, rs2_data_reg = 0, imm_reg = 0, PC_reg = 0;
21	
22	    always @(posedge clk) begin
23	        if (EN & ~state) begin
24	            state <= 1'b1;
25	            JALR_reg <= JALR;
26	            cmp_ctrl_reg <= cmp_ctrl;
27	            rs1_data_reg <= rs1_data;
28	            rs2_data_reg <= rs2_data;
29	            imm_reg <= imm;
30	            PC_reg <= PC;
31	        end
32	        else if (state) begin
33	            state <= 1'b0;
34	        end
35	    end
36	
37	    cmp_32 cmp(.a(rs1_data_reg), .b(rs2_data_reg), .ctrl(cmp_ctrl_reg[3:1]), .c(cmp_res));
38	
39	    wire[31:0] jump_base;
40	    MUX2T1_32 mux_jump_base(.I0(PC_reg), .I1(rs1_data_reg), .s(JALR_reg), .o(jump_base));
41	
42	    add_32 add_jump(.a(jump_base), .b(imm_reg), .c(PC_jump));
43	    add_32 add_wb(.a(PC_reg), .b(32'd4), .c(PC_wb));
44	
45	    assign is_jump = cmp_ctrl_reg[0] | cmp_res;
46	
47	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_mem(
4	    input clk, EN, mem_w,
5	    input[2:0] bhw,
6	    input[31:0] rs1_data, rs2_data, imm,
7	    output[31:0] mem_data,
8	    output finish
9	);
10	
11	    reg[1:0] state;
12	    assign finish = state[0] == 1'b1;
13	    initial begin
14	        state = 0;
15	    end
16	
17	    reg mem_w_reg;
18	    reg[2:0] bhw_reg;
19	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;
20	
21	    wire[31:0] addr;
22	
23	    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));
24	
25	    RAM_B ram(
26	        .addra(addr),
27	        .clka(clk),
28	        .dina(rs2_data_reg),
29	        .wea(mem_w_reg & state[1]),
30	        .douta(mem_data),
31	        .mem_u_b_h_w(bhw_reg),
32	        .finish(finish)
33	    );
34	
35	    always @(posedge clk) begin
36	        if (EN & ~|state) begin
37	            state <= 2'b10;
38	            mem_w_reg <= mem_w;
39	            bhw_reg <= bhw;
40	            rs1_data_reg <= rs1_data;
41	            rs2_data_reg <= rs2_data;
42	            imm_reg <= imm;
43	        end
44	        else begin
45	            state <= {1'b0, state[1]};
46	        end
47	    end
48	
49	endmodule

1	`timescale 1ns / 1ps
2	`include "CtrlDefine.vh"
3	
4	module CtrlUnit(
5	    input[31:0] inst,
6	    
7	    // FU
8	    output  ALU_use, MEM_use, MUL_use, DIV_use, JUMP_use,
9	       
10	    // oprands
11	    output [4:0] rs1_ctrl, rs2_ctrl, dst_ctrl,
12	    output ALU_use_PC,
13	    output ALU_use_imm,
14	    output[2:0] ImmSel,
15	    
16	    // ops
17	    output [4:0] op
18	);
19	   
20	    wire[6:0] funct7 = inst[31:25];
21	    wire[2:0] funct3 = inst[14:12];
22	    wire[6:0] opcode = inst[6:0];
23	    wire[4:0] rd = inst[11:7];
24	    wire[4:0] rs1 = inst[19:15];
25	    wire[4:0] rs2 = inst[24:20];
26	
27	    wire Rop = opcode == 7'b0110011;
28	    wire Iop = opcode == 7'b0010011;
29	    wire Bop = opcode == 7'b1100011;
30	    wire Lop = opcode == 7'b0000011;
31	    wire Sop = opcode == 7'b0100011;
32	
33	    wire funct7_0  = funct7 == 7'h0;
34	    wire funct7_1  = funct7 == 7'h1;
35	    wire funct7_32 = funct7 == 7'h20;
36	
37	    wire funct3_0 = funct3 == 3'h0;
38	    wire funct3_1 = funct3 == 3'h1;
39	    wire funct3_2 = funct3 == 3'h2;
40	    wire funct3_3 = funct3 == 3'h3;
41	    wire funct3_4 = funct3 == 3'h4;
42	    wire funct3_5 = funct3 == 3'h5;
43	    wire funct3_6 = funct3 == 3'h6;
44	    wire funct3_7 = funct3 == 3'h7;
45	
46	    wire ADD  = Rop & funct3_0 & funct7_0;
47	    wire SUB  = Rop & funct3_0 & funct7_32;
48	    wire SLL  = Rop & funct3_1 & funct7_0;
49	    wire SLT  = Rop & funct3_2 & funct7_0;
50	    wire SLTU = Rop & funct3_3 & funct7_0;
51	    wire XOR  = Rop & funct3_4 & funct7_0;
52	    wire SRL  = Rop & funct3_5 & funct7_0;
53	    wire SRA  = Rop & funct3_5 & funct7_32;
54	    wire OR   = Rop & funct3_6 & funct7_0;
55	    wire AND  = Rop & funct3_7 & funct7_0;
56	
57	    wire MUL    = Rop & funct3_0 & funct7_1;
58	    wire MULH   = Rop & funct3_1 & funct7_1;
59	    wire MULHSU = Rop & funct3_2 & funct7_1;
60	    wire MULHU  = Rop & funct3_3 & funct7_1;
61	    wire DIV    = Rop & funct3_4 & funct7_1;
62	    wire DIVU   = Rop & funct3_5 & funct7_1;
63	    wire REM    = Rop & funct3_6 & funct7_1;
64	    wire REMU    = Rop & funct3_7 & funct7_1;
65	
66	    wire ADDI  = Iop & funct3_0;	
67	    wire SLTI  = Iop & funct3_2;
68	    wire SLTIU = Iop & funct3_3;
69	    wire XORI  = Iop & funct3_4;
70	    wire ORI   = Iop & funct3_6;
71	    wire ANDI  = Iop & funct3_7;
72	    wire SLLI  = Iop & funct3_1 & funct7_0;
73	    wire SRLI  = Iop & funct3_5 & funct7_0;
74	    wire SRAI  = Iop & funct3_5 & funct7_32;
75	
76	    wire BEQ = Bop & funct3_0;
77	    wire BNE = Bop & funct3_1;
78	    wire BLT = Bop & funct3_4;
79	    wire BGE = Bop & funct3_5;
80	    wire BLTU = Bop & funct3_6;
81	    wire BGEU = Bop & funct3_7;
82	
83	    wire LB =  Lop & funct3_0;
84	    wire LH =  Lop & funct3_1;
85	    wire LW =  Lop & funct3_2;
86	    wire LBU = Lop & funct3_4;
87	    wire LHU = Lop & funct3_5;
88	
89	    wire SB = Sop & funct3_0;
90	    wire SH = Sop & funct3_1;
91	    wire SW = Sop & funct3_2;
92	
93	    wire LUI   = opcode == 7'b0110111;
94	    wire AUIPC = opcode == 7'b0010111;
95	
96	    wire JAL  =  opcode == 7'b1101111;
97	    wire JALR = (opcode == 7'b1100111) && funct3_0;
98	
99	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU 
100	        | MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
101	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
102	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
103	    wire L_valid = LW | LH | LB | LHU | LBU;
104	    wire S_valid = SW | SH | SB;
105	
106	    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU
107	        | I_valid | LUI | AUIPC;
108	    wire use_MEM = L_valid | S_valid;
109	    wire use_MUL = MUL | MULH | MULHSU | MULHU;
110	    wire use_DIV = DIV | DIVU | REM | REMU;
111	    wire use_JUMP = B_valid | JAL | JALR;
112	
113	    // FU routing
114	    assign ALU_use  = use_ALU;
115	    assign MEM_use  = use_MEM;
116	    assign MUL_use  = use_MUL;
117	    assign DIV_use  = use_DIV;
118	    assign JUMP_use = use_JUMP;
119	
120	    // operation encoding, see CtrlDefine.vh
121	    assign op = {5{ADD}}          & `ALU_ADD    |
122	                {5{SUB}}          & `ALU_SUB    |
123	                {5{AND}}          & `ALU_AND    |
124	                {5{OR}}           & `ALU_OR     |
125	                {5{XOR}}          & `ALU_XOR    |
126	                {5{SLL}}          & `ALU_SLL    |
127	                {5{SRL}}          & `ALU_SRL    |
128	                {5{SLT}}          & `ALU_SLT    |
129	                {5{SLTU}}         & `ALU_SLTU   |
130	                {5{SRA}}          & `ALU_SRA    |
131	                {5{LUI}}          & `ALU_LUI    |
132	                {5{AUIPC}}        & `ALU_AUIPC  |
133	                {5{ADDI}}         & `ALU_ADDI   |
134	                {5{ANDI}}         & `ALU_ANDI   |
135	                {5{ORI}}          & `ALU_ORI    |
136	                {5{XORI}}         & `ALU_XORI   |
137	                {5{SLLI}}         & `ALU_SLLI   |
138	                {5{SRLI}}         & `ALU_SRLI   |
139	                {5{SLTI}}         & `ALU_SLTI   |
140	                {5{SLTIU}}        & `ALU_SLTIU  |
141	                {5{SRAI}}         & `ALU_SRAI   |
142	                {5{LB}}           & `MEM_LB     |
143	                {5{LH}}           & `MEM_LH     |
144	                {5{LW}}           & `MEM_LW     |
145	                {5{LBU}}          & `MEM_LBU    |
146	                {5{LHU}}          & `MEM_LHU    |
147	                {5{SB}}           & `MEM_SB     |
148	                {5{SH}}           & `MEM_SH     |
149	                {5{SW}}           & `MEM_SW     |
150	                {5{MUL}}          & `MUL_MUL    |
151	                {5{MULH}}         & `MUL_MULH   |
152	                {5{MULHSU}}       & `MUL_MULHU  |
153	                {5{MULHU}}        & `MUL_MULHSU |
154	                {5{DIV}}          & `DIV_DIV    |
155	                {5{DIVU}}         & `DIV_DIVU   |
156	                {5{REM}}          & `DIV_REM    |
157	                {5{REMU}}         & `DIV_REMU   |
158	                {5{BEQ}}          & `JUMP_BEQ   |
159	                {5{BNE}}          & `JUMP_BNE   |
160	                {5{BLT}}          & `JUMP_BLT   |
161	                {5{BGE}}          & `JUMP_BGE   |
162	                {5{BLTU}}         & `JUMP_BLTU  |
163	                {5{BGEU}}         & `JUMP_BGEU  |
164	                {5{JAL}}          & `JUMP_JAL   |
165	                {5{JALR}}         & `JUMP_JALR  ;
166	
167	    // register addresses (0 means "not used", so RAT lookup yields no dependency)
168	    assign dst_ctrl = {5{R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR}} & rd;
169	    assign rs1_ctrl = {5{R_valid | I_valid | S_valid | L_valid | B_valid | JALR}} & rs1;
170	    assign rs2_ctrl = {5{R_valid | S_valid | B_valid}} & rs2;
171	
172	    // operand selection for the ALU RS (Vk is taken from the immediate field)
173	    assign ALU_use_PC  = AUIPC;
174	    assign ALU_use_imm = I_valid | LUI | AUIPC;
175	
176	    assign ImmSel = {3{JALR | L_valid | I_valid}} & `Imm_type_I |
177	                    {3{B_valid}}                  & `Imm_type_B |
