3	module FU_ALU(
4	    input clk, EN,
5	    input[3:0] ALUControl,
6	    input[31:0] ALUA, ALUB,
7	    output[31:0] res,
8	    output zero, overflow,
9	    output finish
10	);
11	
12	    reg state;
13	    assign finish = state == 1'b1;
14	    initial begin
15	        state = 0;
16	    end
17	
18	    localparam ALU_ADD  = 4'b0001;
19	    localparam ALU_SUB  = 4'b0010;
20	    localparam ALU_AND  = 4'b0011;
21	    localparam ALU_OR   = 4'b0100;
22	    localparam ALU_XOR  = 4'b0101;
23	    localparam ALU_SLL  = 4'b0110;
24	    localparam ALU_SRL  = 4'b0111;
25	    localparam ALU_SLT  = 4'b1000;
26	    localparam ALU_SLTU = 4'b1001;
27	    localparam ALU_SRA  = 4'b1010;
28	    localparam ALU_Ap4  = 4'b1011;
29	    localparam ALU_Bout = 4'b1100;
30	
31	    reg[3:0] ALUControl_reg;
32	    reg[31:0] ALUA_reg, ALUB_reg;
33	
34	    always @(posedge clk) begin
35	        if (EN & ~state) begin
36	            state <= 1'b1;
37	            ALUControl_reg <= ALUControl;
38	            ALUA_reg <= ALUA;
39	            ALUB_reg <= ALUB;
40	        end
41	        else if (state) begin
42	            state <= 1'b0;
43	        end
44	    end
45	
46	    wire[31:0] res_ADD  = ALUA_reg + ALUB_reg;
47	    wire[31:0] res_SUB  = ALUA_reg - ALUB_reg;
48	    wire[31:0] res_AND  = ALUA_reg & ALUB_reg;
49	    wire[31:0] res_OR   = ALUA_reg | ALUB_reg;
50	    wire[31:0] res_XOR  = ALUA_reg ^ ALUB_reg;
51	    wire[31:0] res_SLL  = ALUA_reg << ALUB_reg[4:0];
52	    wire[31:0] res_SRL  = ALUA_reg >> ALUB_reg[4:0];
53	    wire[31:0] res_SLT  = ($signed(ALUA_reg) < $signed(ALUB_reg)) ? 32'd1 : 32'd0;
54	    wire[31:0] res_SLTU = (ALUA_reg < ALUB_reg) ? 32'd1 : 32'd0;
55	    wire[31:0] res_SRA  = $signed(ALUA_reg) >>> ALUB_reg[4:0];
56	    wire[31:0] res_Ap4  = ALUA_reg + 32'd4;
57	    wire[31:0] res_Bout = ALUB_reg;
58	
59	    assign res = ALUControl_reg == ALU_ADD  ? res_ADD  :
60	                 ALUControl_reg == ALU_SUB  ? res_SUB  :
61	                 ALUControl_reg == ALU_AND  ? res_AND  :
62	                 ALUControl_reg == ALU_OR   ? res_OR   :
63	                 ALUControl_reg == ALU_XOR  ? res_XOR  :
64	                 ALUControl_reg == ALU_SLL  ? res_SLL  :
65	                 ALUControl_reg == ALU_SRL  ? res_SRL  :
66	                 ALUControl_reg == ALU_SLT  ? res_SLT  :
67	                 ALUControl_reg == ALU_SLTU ? res_SLTU :
68	                 ALUControl_reg == ALU_SRA  ? res_SRA  :
69	                 ALUControl_reg == ALU_Ap4  ? res_Ap4  :
70	                 ALUControl_reg == ALU_Bout ? res_Bout : 32'b0;
71	
72	    assign zero = ~|res;
73	
74	    assign overflow = (ALUControl_reg == ALU_ADD &
75	                       (ALUA_reg[31] == ALUB_reg[31]) & (res[31] != ALUA_reg[31])) |
76	                      (ALUControl_reg == ALU_SUB &
77	                       (ALUA_reg[31] != ALUB_reg[31]) & (res[31] != ALUA_reg[31]));
78	
79	endmodule

