23	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
24	    wire is_uart = addra == SIM_UART_ADDR;
25	    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
26	    wire word_op = mem_u_b_h_w[1];
27	    wire half_op = mem_u_b_h_w[0];
28	    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
29	    wire sign_ext = ~mem_u_b_h_w[2];
30	
31	    // Byte-addressable write logic (UART writes excluded, they only produce
32	    // simulation output). Written on the negative edge so store data latched
33	    // at the positive edge is stable.
34	    always @(negedge clka) begin
35	        if (wea && !is_uart) begin
36	            data[addr] <= dina[7:0];
37	            if (half_op | word_op) begin
38	                data[addr + 1] <= dina[15:8];
39	                if (word_op) begin
40	                    data[addr + 2] <= dina[23:16];
41	                    data[addr + 3] <= dina[31:24];
42	                end
43	            end
44	        end
45	    end
46	
47	    // Byte-addressable read logic with sign/zero extension (little endian).
48	    wire[7:0] b0 = data[addr];
49	    wire[7:0] b1 = data[addr + 1];
50	    wire[7:0] b2 = data[addr + 2];
51	    wire[7:0] b3 = data[addr + 3];
52	    wire[31:0] word_r = {b3, b2, b1, b0};
53	    wire[31:0] half_r = {{16{sign_ext & b1[7]}}, b1, b0};
54	    wire[31:0] byte_r = {{24{sign_ext & b0[7]}}, b0};
