`timescale 1ns / 1ps

// Lab6 (Tomasulo OoO core) verification testbench — program 1 (core/rom.mem, test.s).
//
// In this core the "WB stage" is the CDB broadcast that commits results into
// the register file inside Regs (instance name `register` in RV32core):
//   - core.cdb_rs_num  : nonzero tag => a result is being broadcast this cycle
//   - core.cdb_data    : write-back data   (also on output port wb_data)
//   - core.cdb_pc      : PC of the instruction (also on output port wb_addr)
//   - destination rd   : the register i whose core.register.rat[i] == cdb_rs_num;
//                        core.register.register[i] <= cdb_data at the negedge.
//
// Hand-executed expectations for test.s with ram.mem data:
//   x2=8 (lw 4)  x4=16 (lw 8)  x1=24 (add)  x1=23 (addi -1)
//   x5=20 (lw 12)  x6=0xFFFF0000 (lw 16)  x7=0x0FFF0000 (lw 20)
//   x1=8 (sub)  x1=0xFFFFFFFD (addi x10,-3)
//   beq x4,x5 not taken; beq x4,x4 taken -> 0x40
//   x1=0x4000 (lui 4)  x1=0x48 (jal +12 -> 0x50)
//   x1=0xFFFF0050 (auipc 0xffff0 @0x50)
//   x8=0x01FFE000 (div x7/8)  x9=0x140 (mul 16*20)  x9=0x0FFF0000 (mul x8*8)
//   x2=4 (addi)  x1=0x68 (jalr 0(x0) -> PC=0, program restarts)

module lab6_tb;

    reg clk, rst;
    wire [31:0] wb_addr, wb_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .wb_addr(wb_addr),
        .wb_data(wb_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #10 rst = 0;
    end
    always #1 clk = ~clk;

    integer cycle = 0;
    integer wb_count = 0;
    integer x_errors = 0;
    integer errors = 0;
    integer logf;
    integer i, rd;
    integer jalr_seen = 0;
    integer checked = 0;

    initial logf = $fopen("wb_log_prog1.txt", "w");

    // WB (CDB commit) monitor
    always @(posedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.cdb_rs_num !== 8'b0) begin
                if (^core.cdb_rs_num === 1'bx || ^core.cdb_data === 1'bx ||
                    ^core.cdb_pc === 1'bx) begin
                    x_errors = x_errors + 1;
                    $display("X/Z on CDB at cycle %0d: rs=%b data=%h pc=%h",
                             cycle, core.cdb_rs_num, core.cdb_data, core.cdb_pc);
                end
                // resolve destination register through the RAT
                rd = -1;
                for (i = 1; i < 32; i = i + 1)
                    if (core.register.rat[i] == core.cdb_rs_num) rd = i;
                wb_count = wb_count + 1;
                if (rd > 0)
                    $fdisplay(logf, "cycle=%0d pc=%h rd=x%0d data=%h",
                              cycle, core.cdb_pc, rd, core.cdb_data);
                else
                    $fdisplay(logf, "cycle=%0d pc=%h rd=- (no reg waits; branch/tag free) data=%h",
                              cycle, core.cdb_pc, core.cdb_data);
                // first pass ends when the jalr @0x64 commits
                if (core.cdb_pc === 32'h64) jalr_seen = jalr_seen + 1;
            end
            // check outputs match internal CDB signals
            if (wb_addr !== core.cdb_pc || wb_data !== core.cdb_data) begin
                $display("MISMATCH wb_addr/wb_data vs cdb at cycle %0d", cycle);
                errors = errors + 1;
            end

            if (jalr_seen == 1 && !checked) begin
                checked = 1;
                @(negedge clk); // let the commit land in the register file
                check_regs;
            end

            if (cycle > 4000) begin
                $display("--- end of sim: %0d WB broadcasts, %0d X/Z errors, %0d errors ---",
                         wb_count, x_errors, errors);
                if (jalr_seen < 2)
                    $display("FAIL: jalr @0x64 committed only %0d times (program should loop back to PC=0 and run again)", jalr_seen);
                else
                    $display("PASS: program looped back and re-ran (jalr committed %0d times)", jalr_seen);
                $finish;
            end
        end
    end

    task expect;
        input [4:0] r;
        input [31:0] v;
        begin
            if (core.register.register[r] !== v) begin
                $display("FAIL: x%0d = %h, expected %h", r, core.register.register[r], v);
                errors = errors + 1;
            end
        end
    endtask

    task check_regs;
        begin
            $display("--- register check after first pass (cycle %0d) ---", cycle);
            expect(1,  32'h00000068); // jalr return address 0x64+4
            expect(2,  32'd4);
            expect(4,  32'd16);
            expect(5,  32'd20);
            expect(6,  32'hFFFF0000);
            expect(7,  32'h0FFF0000);
            expect(8,  32'h01FFE000);
            expect(9,  32'h0FFF0000);
            for (i = 10; i < 32; i = i + 1) expect(i[4:0], 32'b0);
            expect(3, 32'b0);
            if (errors == 0 && x_errors == 0)
                $display("PASS: all register values match hand-executed expectations");
        end
    endtask

endmodule

